import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Updates, backups and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"en/operations/maintenance.md","filePath":"en/operations/maintenance.md","lastUpdated":1794405696000}`),a={name:`en/operations/maintenance.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="updates-backups-and-recovery" tabindex="-1">Updates, backups and recovery <a class="header-anchor" href="#updates-backups-and-recovery" aria-label="Permalink to “Updates, backups and recovery”">​</a></h1><h2 id="update-basics" tabindex="-1">Update basics <a class="header-anchor" href="#update-basics" aria-label="Permalink to “Update basics”">​</a></h2><p>Commit your implementation, deploy to Preview after testing, then release to production by specifying the commit you finished checking. See the <a href="./../getting-started/preview-production">update commands</a>.</p><p>Changes to campaigns and the shared design are made in the admin console. Saving a draft, starting delivery of a campaign and deploying the whole system are separate operations.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to “Backups”">​</a></h2><p>On Cloudflare, note the D1 Time Travel restore point and the code commit, and export if needed.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DB</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup.sql</span></span></code></pre></div><p>The admin database contains not only settings but also emails, passkey public keys, sessions, invitations and so on. Restrict access to backups.</p><p>On Node.js, keep the SQLite file and the WAL consistent. Back up while stopped or use a SQLite-aware backup method, and secure a persistent disk.</p><p>There is no feature to back up or restore visitors&#39; behavior history from the server.</p><h2 id="migrating-from-the-old-admin-token-method" tabindex="-1">Migrating from the old admin-token method <a class="header-anchor" href="#migrating-from-the-old-admin-token-method" aria-label="Permalink to “Migrating from the old admin-token method”">​</a></h2><p>An additional migration creates the admin tables. It doesn&#39;t delete the existing app_config, and when the first superuser registration succeeds, it copies the latest sites at that point. Site and campaign IDs and existing questions are kept.</p><p>After the switch, admin_sites is used and updates to the old app_config are frozen. You can&#39;t get into the normal admin APIs with the old token. Removing AUTH_MODE doesn&#39;t return to the old method automatically.</p><h2 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to “Rolling back”">​</a></h2><p>Reverting only the code to an older version may be inconsistent with the new settings in the database. Prioritize updating to a fix that keeps the additional migrations.</p><p>To go back to the past, align the code and database restore points during maintenance and check which admin operations would be lost. Don&#39;t truncate questions without notice to convert them to an old format.</p><h2 id="account-recovery" tabindex="-1">Account recovery <a class="header-anchor" href="#account-recovery" aria-label="Permalink to “Account recovery”">​</a></h2><p>Normally you use a spare passkey, recovery codes or a superuser&#39;s time-limited recovery link. See <a href="./../guides/accounts">accounts</a>.</p><p>If every superuser loses their credentials, an environment operator who can operate the database responds, after verifying identity and taking a backup. There is no public back door that retakes an existing account with ADMIN_TOKEN. The final steps for operators are in the <a href="https://github.com/manji6/jev-personalization/blob/main/docs/admin-v2-setup.md" target="_blank" rel="noreferrer">repository&#39;s migration and recovery guide</a>.</p><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to “Health checks”">​</a></h2><p><code>/health</code> only confirms that the process responds. It doesn&#39;t guarantee Jev&#39;s balance, correct audience judgments or the validity of every secret. In Preview, the entrance is also protected by Access.</p><p>During a model failure, congestion or a cost limit, it continues without showing offers. Check that you can operate the target site itself, and check the reasons in the diagnostic panel.</p><h2 id="site-only-jev-keys-and-usage-records" tabindex="-1">Site-only Jev keys and usage records <a class="header-anchor" href="#site-only-jev-keys-and-usage-records" aria-label="Permalink to “Site-only Jev keys and usage records”">​</a></h2><p>Backups also contain the ciphertext of API keys and the usage records. Protect and store the matching encryption key separately from the database. Old records are deleted during normal use and viewing, but backup retention is managed separately. For updating, losing and rolling back the encryption key, see the <a href="./jev-keys">dedicated steps</a>. Rolling back to only code that predates this support could ignore site-only keys or a stop and use a shared key.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};